mapper.select:
SELECT * FROM (
    SELECT CASE_ID, CASE_NO, APPLICANT_NAME, APPLIED_ON, BENEFITS, DEADLINE, EXTEND_REASON, STATUS, ASSIGNEE_NAME, DECIDED_ON
      FROM WELFARE_CASE

        STATUS IN ('RECEIVED', 'SURVEY')
        STATUS = #{status}
        AND (CASE_NO LIKE '%' || #{q} || '%' OR APPLICANT_NAME LIKE '%' || #{q} || '%')

     ORDER BY CASE WHEN STATUS IN ('RECEIVED', 'SURVEY') THEN 0 ELSE 1 END, DEADLINE, CASE_ID DESC
) WHERE ROWNUM <= #{limit}
